package com.example.lending.adapter.in.web;

import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookAvailableException;
import com.example.lending.domain.BookDiscardedException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.BookOnLoanException;
import com.example.lending.domain.BookReservedForOtherException;
import com.example.lending.domain.LoanAlreadyReturnedException;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.LoanNotFoundException;
import com.example.lending.domain.MemberAlreadyExistsException;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.ReservationAlreadyExistsException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    public ProblemDetail handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }

    @ExceptionHandler(BookOnLoanException.class)
    public ResponseEntity<Map<String, String>> handleBookOnLoanForDiscard(BookOnLoanException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_ON_LOAN"));
    }

    @ExceptionHandler(BookDiscardedException.class)
    public ResponseEntity<Map<String, String>> handleBookDiscarded(BookDiscardedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_DISCARDED"));
    }

    @ExceptionHandler(BookAvailableException.class)
    public ResponseEntity<Map<String, String>> handleBookAvailable(BookAvailableException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "BOOK_AVAILABLE"));
    }

    @ExceptionHandler(BookReservedForOtherException.class)
    public ResponseEntity<Map<String, String>> handleReservedForOther(BookReservedForOtherException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "RESERVED_FOR_OTHER"));
    }

    @ExceptionHandler(ReservationAlreadyExistsException.class)
    public ResponseEntity<Map<String, String>> handleReservationAlreadyExists(ReservationAlreadyExistsException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "ALREADY_RESERVED"));
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    public ResponseEntity<Map<String, String>> handleLoanLimitExceeded(LoanLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "LOAN_LIMIT_EXCEEDED"));
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    public ResponseEntity<Map<String, String>> handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "ALREADY_RETURNED"));
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberAlreadyExistsException.class)
    public ResponseEntity<Map<String, String>> handleMemberAlreadyExists(MemberAlreadyExistsException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", "MEMBER_ALREADY_EXISTS"));
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
package com.example.lending.domain;

import com.example.lending.common.DateUtils;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;
    public static final int MAX_LOANS_PER_MEMBER = 5;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        if (returnedAt != null && returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, DateUtils.addDays(loanedAt, LOAN_PERIOD_DAYS), null);
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    }

    public void returnOn(LocalDate returnedAt) {
        if (isReturned()) {
            throw new LoanAlreadyReturnedException(id);
        }
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    // 기한 당일 반납은 연체가 아니며, 기한을 넘긴 날짜마다 연체일로 센다.
    public long overdueDays() {
        if (!isReturned() || !returnedAt.isAfter(dueAt)) {
            return 0;
        }
        return ChronoUnit.DAYS.between(dueAt, returnedAt);
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }
}
package com.example.lending.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;

import java.util.Objects;
import java.util.UUID;

@Entity
public class Member {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String name;

    protected Member() {
    }

    private Member(UUID id, String name) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
    }

    public static Member register(String name) {
        return new Member(UUID.randomUUID(), name);
    }

    public static Member register(UUID id, String name) {
        return new Member(id, name);
    }

    public static Member reconstitute(UUID id, String name) {
        return new Member(id, name);
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.LocalDate;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    @Column
    private LocalDate returnedAt;

    protected LoanJpaEntity() {
    }

    public LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Loan;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(),
                entity.getLoanedAt(), entity.getDueAt(), entity.getReturnedAt());
    }

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(),
                loan.getLoanedAt(), loan.getDueAt(), loan.getReturnedAt());
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoan;
import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoanPage;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements LoadLoanPort, SaveLoanPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public long countActiveByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findByIdForUpdate(loanId).map(loanMapper::toDomain);
    }

    @Override
    public ActiveLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        Page<ActiveLoanRow> rows = loanJpaRepository.findActiveLoanRowsByMemberId(memberId, PageRequest.of(page, size));
        List<ActiveLoan> items = rows.getContent().stream()
                .map(row -> new ActiveLoan(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
        return new ActiveLoanPage(items, page, size, rows.getTotalElements());
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }
}

