package com.example.lending.application.service;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.LoadReservationPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookAlreadyOnLoanException;
import com.example.lending.domain.BookDiscardedException;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.BookReservedForOtherException;
import com.example.lending.domain.BookStatus;
import com.example.lending.domain.Loan;
import com.example.lending.domain.LoanLimitExceededException;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.UUID;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    // 도서관 후원자 회원. 대출 권수 제한을 적용하지 않는다.
    private static final Set<UUID> LOAN_LIMIT_EXEMPT_MEMBER_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final LoadMemberPort loadMemberPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadReservationPort loadReservationPort;
    private final SaveReservationPort saveReservationPort;

    public LoanBookService(LoadMemberPort loadMemberPort, LoadBookPort loadBookPort, SaveBookPort saveBookPort,
                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort,
                           LoadReservationPort loadReservationPort, SaveReservationPort saveReservationPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadReservationPort = loadReservationPort;
        this.saveReservationPort = saveReservationPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        // 회원 행을 잠가 같은 회원의 동시 대출 요청이 한도 검사를 함께 통과하지 못하게 한다.
        loadMemberPort.loadMemberForUpdate(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        if (!LOAN_LIMIT_EXEMPT_MEMBER_IDS.contains(command.memberId())
                && loadLoanPort.countActiveByMemberId(command.memberId()) >= Loan.MAX_LOANS_PER_MEMBER) {
            throw new LoanLimitExceededException(command.memberId());
        }
        // 도서 행을 잠가 같은 도서에 대한 대출 요청과 폐기 요청이 함께 상태 검사를 통과하지 못하게 한다.
        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        if (book.getStatus() == BookStatus.DISCARDED) {
            throw new BookDiscardedException(book.getId());
        }
        if (book.getStatus() == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(book.getId());
        }
        // 예약이 있는 도서는 맨 앞 예약자만 빌릴 수 있고, 빌리면 그 예약을 소진한다.
        List<Reservation> queue = loadReservationPort.loadReservationsByBookId(book.getId());
        if (!queue.isEmpty()) {
            Reservation head = queue.get(0);
            if (!head.getMemberId().equals(command.memberId())) {
                throw new BookReservedForOtherException(book.getId());
            }
            saveReservationPort.deleteReservation(head.getId());
        }
        LocalDate loanedAt = command.loanedAt() != null ? command.loanedAt() : LocalDate.now();
        Loan loan = Loan.start(book.getId(), command.memberId(), loanedAt);
        book.setStatus(BookStatus.ON_LOAN);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
    }
}

