public record LoanDetailResponse(UUID loanId, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                 CreditCheckView creditCheck) {

    static LoanDetailResponse from(Loan loan) {
        return new LoanDetailResponse(loan.getId(), loan.getBookId(), loan.getMemberId(),
                loan.getLoanedAt(), loan.getDueAt(), CreditCheckView.from(loan.getCreditCheck()));
    }

    public record CreditCheckView(boolean approved, int score, Instant checkedAt) {

        static CreditCheckView from(CreditCheck creditCheck) {
            if (creditCheck == null) {
                return null;
            }
            return new CreditCheckView(creditCheck.approved(), creditCheck.score(), creditCheck.checkedAt());
        }
    }
}
