package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CreditCheckApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void a_member_rejected_by_credit_check_gets_409_and_the_book_stays_loanable() throws Exception {
        String bookId = registerBook();
        String blockedMemberId = registerMember("BLOCKED-kim");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, blockedMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("CREDIT_REJECTED"));

        String otherMemberId = registerMember("이준호");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, otherMemberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void approved_loan_returns_the_stored_credit_check_result() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember("김민지");

        String created = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String loanId = objectMapper.readTree(created).get("loanId").asText();

        mockMvc.perform(get("/loans/{loanId}", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.bookId").value(bookId))
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.dueAt").exists())
                .andExpect(jsonPath("$.creditCheck.approved").value(true))
                .andExpect(jsonPath("$.creditCheck.score").value(742))
                .andExpect(jsonPath("$.creditCheck.checkedAt").exists());
    }

    @Test
    void getting_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(get("/loans/{loanId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Effective Java\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    String loanBody(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record LoanBody(String bookId, String memberId) {
    }
}
